def calc(expr):
    toks = []
    i = 0
    while i < len(expr):
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif ch.isdigit() or ch == '.':
            j = i
            while j < len(expr) and (expr[j].isdigit() or expr[j] == '.'):
                j += 1
            toks.append(float(expr[i:j]))
            i = j
        else:
            toks.append(ch)
            i += 1
    pos = [0]
    def peek():
        return toks[pos[0]] if pos[0] < len(toks) else None
    def eat():
        pos[0] += 1
        return toks[pos[0] - 1]
    def expr_():
        v = term()
        while peek() in ('+', '-'):
            op = eat()
            r = term()
            v = v + r if op == '+' else v - r
        return v
    def term():
        v = unary()
        while peek() in ('*', '/'):
            op = eat()
            r = unary()
            v = v * r if op == '*' else v / r
        return v
    def unary():
        if peek() == '-':
            eat()
            return -unary()
        if peek() == '(':
            eat()
            v = expr_()
            eat()
            return v
        return eat()
    return expr_()
